export function timeMapOperations(operations                       )                    {
  const store=new Map                                     (),result                =[]; for(const op of operations) { const name=op[0]          ,key=op[1]          ; if(name==='set') { const history=store.get(key)??[];history.push({time:op[3]          ,value:op[2]          });store.set(key,history);result.push(null); } else { const history=store.get(key)??[],time=op[2]          ; let low=0,high=history.length;while(low<high) { const mid=Math.floor((low+high)/2);if(history[mid].time<=time)low=mid+1;else high=mid; } result.push(low===0?'':history[low-1].value); } } return result;
}

