export function timeMapOperations(operations: (string | number)[][]): (string | null)[] {
  const store=new Map<string,{time:number;value:string}[]>(),result:(string|null)[]=[]; for(const op of operations) { const name=op[0] as string,key=op[1] as string; if(name==='set') { const history=store.get(key)??[];history.push({time:op[3] as number,value:op[2] as string});store.set(key,history);result.push(null); } else { const history=store.get(key)??[],time=op[2] as number; let low=0,high=history.length;while(low<high) { const mid=Math.floor((low+high)/2);if(history[mid].time<=time)low=mid+1;else high=mid; } result.push(low===0?'':history[low-1].value); } } return result;
}
